const cfg = $('Set Catalog Config').first().json;
const item = $input.first();
const headers = item.json.headers || {};

// ---- SHA-256 / HMAC (pure JS, no modules needed) ----
const primes = []; for (let n = 2; primes.length < 64; n++) if (primes.every(p => n % p)) primes.push(n);
const frac = x => Math.floor((x - Math.floor(x)) * 4294967296);
const K = primes.map(p => frac(Math.cbrt(p))), H0 = primes.slice(0, 8).map(p => frac(Math.sqrt(p)));
const rotr = (x, n) => (x >>> n) | (x << (32 - n));
function sha256(msg) {
  const b = msg.slice(), l = b.length;
  b.push(0x80); while (b.length % 64 !== 56) b.push(0);
  const hi = Math.floor(l * 8 / 4294967296), lo = (l * 8) >>> 0;
  for (let i = 3; i >= 0; i--) b.push((hi >>> (i * 8)) & 255);
  for (let i = 3; i >= 0; i--) b.push((lo >>> (i * 8)) & 255);
  const H = H0.slice();
  for (let off = 0; off < b.length; off += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = ((b[off + 4 * i] << 24) | (b[off + 4 * i + 1] << 16) | (b[off + 4 * i + 2] << 8) | b[off + 4 * i + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3), s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, bb, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & bb) ^ (a & c) ^ (bb & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = bb; bb = a; a = (t1 + t2) >>> 0;
    }
    [a, bb, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  const out = []; H.forEach(x => { for (let i = 3; i >= 0; i--) out.push((x >>> (i * 8)) & 255); });
  return out;
}
function hmac(key, msg) {
  if (key.length > 64) key = sha256(key);
  const k = key.concat(new Array(64 - key.length).fill(0));
  return sha256(k.map(x => x ^ 0x5c).concat(sha256(k.map(x => x ^ 0x36).concat(msg))));
}
const bytes = s => Array.from(Buffer.from(s, 'utf8'));
const hex = a => a.map(x => x.toString(16).padStart(2, '0')).join('');
const parseForm = s => { const o = {}; String(s || '').split('&').forEach(p => { if (!p) return; const i = p.indexOf('='); o[decodeURIComponent((i < 0 ? p : p.slice(0, i)).replace(/\+/g, ' '))] = i < 0 ? '' : decodeURIComponent(p.slice(i + 1).replace(/\+/g, ' ')); }); return o; };
const reject = reason => [{ json: { kind: 'rejected', reason } }];

let raw = null;
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); } catch (e) {}
if (raw === null && item.binary && item.binary.data && item.binary.data.data) { try { raw = Buffer.from(item.binary.data.data, 'base64').toString('utf8'); } catch (e) {} }

if (cfg.verifySignatures !== false) {
  if (raw === null) return reject('raw request body not available');
  const ts = String(headers['x-slack-request-timestamp'] || ''), sig = String(headers['x-slack-signature'] || '');
  if (!ts || !sig || Math.abs(Date.now() / 1000 - Number(ts)) > 300) return reject('missing or stale timestamp');
  const expected = 'v0=' + hex(hmac(bytes(String(cfg.signingSecret)), bytes('v0:' + ts + ':' + raw)));
  let diff = expected.length ^ sig.length;
  for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ (sig.charCodeAt(i) || 0);
  if (diff !== 0) return reject('invalid signature');
}
const form = raw !== null ? parseForm(raw) : (item.json.body || {});
if (form.payload) { try { return [{ json: { kind: 'interactive', payload: JSON.parse(form.payload) } }]; } catch (e) { return reject('invalid payload'); } }
if (form.command) return [{ json: { kind: 'slash', form } }];
return reject('unknown request');

const items = $input.all().map(i => i.json).filter(r => r.item_id);
const v = $('Code - Verify Slack Request').first().json;
const t = (s, n) => String(s || '').slice(0, n);
const pt = text => ({ type: 'plain_text', text });
const byCat = {};
items.slice(0, 100).forEach(i => { (byCat[i.category] = byCat[i.category] || []).push({ text: pt(t(i.name, 75)), description: pt(t(i.description, 75)), value: i.item_id }); });
const view = { type: 'modal', callback_id: 'catalog_select', title: pt('IT Service Catalog'), close: pt('Cancel'),
  blocks: items.length ? [{ type: 'input', block_id: 'item_block', label: pt('What do you need?'),
    element: { type: 'static_select', action_id: 'item', placeholder: pt('Choose a service'), option_groups: Object.entries(byCat).map(([label, options]) => ({ label: pt(t(label, 75)), options })) } }]
    : [{ type: 'section', text: { type: 'mrkdwn', text: 'No services are available yet.' } }] };
if (items.length) view.submit = pt('Next');
return [{ json: { trigger_id: v.form.trigger_id, view } }];

const p = $input.first().json.payload;
const out = { payload: p, route: 'ignore', itemId: null };
if (p.type === 'view_submission' && p.view) {
  if (p.view.callback_id === 'catalog_select') {
    const o = (((p.view.state.values.item_block || {}).item) || {}).selected_option;
    out.route = 'select_item'; out.itemId = o ? o.value : null;
  } else if (p.view.callback_id === 'catalog_request') {
    let m = {}; try { m = JSON.parse(p.view.private_metadata || '{}'); } catch (e) {}
    out.route = 'submit_request'; out.itemId = m.itemId || null;
  }
} else if (p.type === 'block_actions' && p.actions && p.actions.length) {
  const id = p.actions[0].action_id;
  if (id === 'approve_request' || id === 'deny_request') out.route = 'approval_decision';
  else if (id === 'complete_request') out.route = 'fulfillment_done';
}
return [{ json: out }];

const row = $input.first().json;
if (!row.item_id) return [{ json: { response: { response_action: 'errors', errors: { item_block: 'This service is no longer available' } } } }];
const parse = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const pt = (text, n = 2000) => ({ type: 'plain_text', text: String(text).slice(0, n) });
const who = { none: 'not required', manager: 'your manager', it: 'the IT lead' }[row.approval];
const blocks = [{ type: 'context', elements: [{ type: 'mrkdwn', text: '*' + row.name + '*: ' + row.description + '\nTarget: ' + row.sla_hours + 'h  |  Approval: ' + who }] }];
for (const f of parse(row.fields)) {
  const element = f.type === 'select'
    ? { type: 'static_select', action_id: 'v', placeholder: pt('Choose'), options: (f.options || []).map(o => ({ text: pt(o, 75), value: String(o).slice(0, 75) })) }
    : { type: 'plain_text_input', action_id: 'v', multiline: f.type === 'textarea' };
  blocks.push({ type: 'input', block_id: 'f_' + f.id, optional: !f.required, label: pt(f.label), element });
}
if (row.approval !== 'none') blocks.push({ type: 'input', block_id: 'justification', label: pt('Business justification'), element: { type: 'plain_text_input', action_id: 'v', multiline: true } });
const view = { type: 'modal', callback_id: 'catalog_request', private_metadata: JSON.stringify({ itemId: row.item_id }), title: pt(row.name, 24), submit: pt('Submit request'), close: pt('Cancel'), blocks };
return [{ json: { response: { response_action: 'update', view } } }];

const p = $('Code - Route Interaction').first().json.payload;
const row = $input.first().json;
const parse = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const values = p.view.state.values;
const get = id => { const v = values[id] && values[id].v; return v ? (v.selected_option ? v.selected_option.value : v.value) : undefined; };
const errors = {}, fields = {};
for (const f of parse(row.fields || '[]')) {
  const v = get('f_' + f.id);
  if (f.required && (v === undefined || v === null || String(v).trim() === '')) errors['f_' + f.id] = 'This field is required';
  else if (v !== undefined && v !== null) {
    if (String(v).length > 500) errors['f_' + f.id] = 'Please keep this under 500 characters';
    else fields[f.id] = String(v).trim();
  }
}
const justification = String(get('justification') || '').trim();
if (row.approval && row.approval !== 'none') {
  if (justification.length < 5) errors.justification = 'Please explain why you need this (at least 5 characters)';
  else if (justification.length > 1000) errors.justification = 'Please keep this under 1000 characters';
}
const requestId = 'REQ-' + Date.now().toString(36).toUpperCase().slice(-5) + Math.random().toString(36).slice(2, 5).toUpperCase();
return [{ json: { valid: !!row.item_id && Object.keys(errors).length === 0, errors, fields, justification, itemId: row.item_id, requestId, requesterSlackId: p.user.id, requesterName: p.user.name || p.user.username || '' } }];

const row = $input.first().json;
const parse = v => (typeof v === 'string' ? JSON.parse(v) : v) || {};
const f = parse(row.fields), ful = parse(row.fulfillment);
const approval = row.status === 'pending_approval';
const details = Object.entries(f).map(([k, v]) => '*' + k + ':* ' + v).join('\n');
const notifyText = approval
  ? ':inbox_tray: Request *' + row.request_id + '* for *' + row.item_name + '* is submitted and waiting for approval from <@' + row.approver_slack_id + '>.'
  : ful.mode === 'auto' ? ':gear: Request *' + row.request_id + '* for *' + row.item_name + '* is submitted. Running it automatically now.'
  : ':inbox_tray: Request *' + row.request_id + '* for *' + row.item_name + '* is submitted and queued for the IT team (target ' + row.sla_hours + 'h).';
const approvalBlocks = [
  { type: 'section', text: { type: 'mrkdwn', text: ':raised_hand: *Approval needed:* <@' + row.requester_slack_id + '> requests *' + row.item_name + '* (' + row.request_id + ')\n' + (details ? details + '\n' : '') + (row.justification ? '*Justification:* ' + row.justification : '') } },
  { type: 'actions', elements: [
    { type: 'button', text: { type: 'plain_text', text: 'Approve' }, style: 'primary', action_id: 'approve_request', value: row.request_id },
    { type: 'button', text: { type: 'plain_text', text: 'Deny' }, style: 'danger', action_id: 'deny_request', value: row.request_id }] }];
return [{ json: { ...row, route: approval ? 'approval' : 'fulfill', notifyChannel: row.requester_slack_id, notifyText,
  approvalText: 'Approval needed for ' + row.item_name + ' (' + row.request_id + ')', approvalBlocks } }];

const p = $('Code - Route Interaction').first().json.payload;
const a = p.actions[0];
return [{ json: { requestId: a.value, decision: a.action_id === 'approve_request' ? 'approved' : 'denied', userId: p.user.id, responseUrl: p.response_url } }];

parameters.query:
WITH u AS (
  UPDATE sc_requests SET status = $2::text, decided_by = $3::text, decided_at = NOW()
  WHERE request_id = $1::text AND status = 'pending_approval' AND approver_slack_id = $3::text
  RETURNING *
), a AS (
  INSERT INTO sc_audit (request_id, event, actor, detail) SELECT request_id, 'decision:' || $2::text, $3::text, NULL FROM u RETURNING 1
)
SELECT u.request_id, u.item_id, i.name AS item_name, u.requester_slack_id, u.requester_name, u.fields, u.justification, u.status, u.approver_slack_id, i.approval, i.fulfillment, i.sla_hours
FROM u JOIN sc_catalog_items i ON i.item_id = u.item_id;

parameters.jsCode:
const r = $input.first().json;
const parse = v => (typeof v === 'string' ? JSON.parse(v) : v) || {};
const fields = parse(r.fields), ful = parse(r.fulfillment);
const details = Object.entries(fields).map(([k, v]) => '*' + k + ':* ' + v).join('\n');
const queueText = ':ticket: *' + r.item_name + '* (' + r.request_id + ') for <@' + r.requester_slack_id + '>, target ' + r.sla_hours + 'h';
const queueBlocks = [
  { type: 'section', text: { type: 'mrkdwn', text: queueText + (r.approver_slack_id ? '\nApproved by <@' + r.approver_slack_id + '>' : '') + (details ? '\n' + details : '') } },
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Mark complete' }, style: 'primary', action_id: 'complete_request', value: r.request_id }] }];
return [{ json: { ...r, mode: ful.mode === 'auto' && ful.url ? 'auto' : 'manual', fulfillment: ful, queueText, queueBlocks,
  automationBody: { requestId: r.request_id, item: r.item_id, requester: { slackId: r.requester_slack_id, name: r.requester_name }, fields, justification: r.justification } } }];

const t = $('Code - Prepare Fulfillment').first().json;
const r = $input.first().json || {};
const sc = Number(r.statusCode) || 0;
const ok = sc >= 200 && sc < 300;
let body = r.body; if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const summary = String((body && body.message) || '').slice(0, 200);
const err = sc ? 'HTTP ' + sc : String((r.error && r.error.message) || 'no response');
return [{ json: { ...t, ok, status: ok ? 'fulfilled' : 'manual_pending', resultJson: JSON.stringify({ statusCode: sc, summary }),
  notifyChannel: t.requester_slack_id,
  notifyText: ok ? ':white_check_mark: Your request *' + t.request_id + '* for *' + t.item_name + '* is done.' + (summary ? ' ' + summary : '')
    : ':warning: The automation for *' + t.request_id + '* (' + t.item_name + ') failed, so the IT team has been alerted and will finish it manually.',
  queueText: ok ? t.queueText : ':warning: Automation failed (' + err + '). Please handle manually.\n' + t.queueText } }];

parameters.query:
WITH u AS (
  UPDATE sc_requests SET status = $2::text, result = $3::jsonb, fulfilled_at = CASE WHEN $2::text = 'fulfilled' THEN NOW() END WHERE request_id = $1::text RETURNING request_id
), a AS (
  INSERT INTO sc_audit (request_id, event, actor, detail) SELECT request_id, 'automation:' || $2::text, 'workflow', $3::text FROM u RETURNING 1
)
SELECT request_id FROM u;

WITH u AS (
  UPDATE sc_requests SET status = 'fulfilled', fulfilled_at = NOW(), result = jsonb_build_object('completedBy', $2::text)
  WHERE request_id = $1::text AND status IN ('approved', 'manual_pending') RETURNING *
), a AS (
  INSERT INTO sc_audit (request_id, event, actor, detail) SELECT request_id, 'completed', $2::text, NULL FROM u RETURNING 1
)
SELECT u.request_id, u.requester_slack_id, i.name AS item_name FROM u JOIN sc_catalog_items i ON i.item_id = u.item_id;
